shader.code:
shader_type spatial;
render_mode unshaded;

uniform float time;
uniform float decay_rate : hint_range(0.0, 1.0) = 0.7;
uniform vec3 void_color = vec3(0.01, 0.0, 0.025);
uniform vec3 memory_trace_color = vec3(0.05, 0.02, 0.1);

void fragment() {
  float energy_flicker = sin(time * 0.8 + UV.x * 10.0) * cos(time * 0.6 + UV.y * 10.0);
  energy_flicker = clamp(energy_flicker * 0.2 + 0.1, 0.0, 0.2);

  float decay_noise = fract(sin(dot(UV + time * 0.1, vec2(12.9898, 78.233))) * 43758.5453);
  decay_noise = smoothstep(0.4, 0.6, decay_noise);

  vec3 final_albedo = mix(memory_trace_color * energy_flicker, void_color, decay_rate * (1.0 - energy_flicker) + decay_noise * 0.3);

  ALBEDO = final_albedo;
  EMISSION = final_albedo * 0.7;
}
